<?php
require '_init.php';$pageTitle='Manage Food';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
if($action==='delete'){$s=$pdo->prepare("DELETE FROM food_items WHERE id=?");$s->execute([$id]);set_flash('Food item deleted.');redirect('foods.php');}
$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT);$cat=(int)($_POST['category_id']??0);$image=trim($_POST['image_url']??'');$available=isset($_POST['is_available'])?1:0;
if($name===''||$price===false||$price<=0||strlen($name)>120){$error='Enter a valid food name and positive price.';}
else{if($action==='add'){$s=$pdo->prepare("INSERT INTO food_items(category_id,name,description,price,image_url,is_available) VALUES(?,?,?,?,?,?)");$s->execute([$cat?:null,$name,$desc,$price,$image,$available]);set_flash('Food item added.');}elseif($action==='edit'){$s=$pdo->prepare("UPDATE food_items SET category_id=?,name=?,description=?,price=?,image_url=?,is_available=? WHERE id=?");$s->execute([$cat?:null,$name,$desc,$price,$image,$available,$id]);set_flash('Food item updated.');}redirect('foods.php');}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM food_items WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();$foods=$pdo->query("SELECT f.*,c.name category_name FROM food_items f LEFT JOIN categories c ON c.id=f.category_id ORDER BY f.created_at DESC")->fetchAll();
require '../includes/header.php';
?>
<section class="page-heading"><span class="eyebrow">ADMIN</span><h1>Manage Food Menu</h1></section>
<div class="admin-layout"><section class="form-card"><h2><?= $edit?'Edit food item':'Add food item' ?></h2><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="post" class="stack-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $edit?'edit':'add' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label>Food name<input name="name" required maxlength="120" value="<?= e($edit['name']??'') ?>"></label><label>Description<textarea name="description" rows="3"><?= e($edit['description']??'') ?></textarea></label><label>Price (PKR)<input type="number" name="price" min="1" step="0.01" required value="<?= e((string)($edit['price']??'')) ?>"></label><label>Category<select name="category_id"><option value="0">Uncategorized</option><?php foreach($cats as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Image URL or emoji<input name="image_url" value="<?= e($edit['image_url']??'🍽') ?>" placeholder="🍔 or https://..."></label><label class="check-label"><input type="checkbox" name="is_available" <?= !isset($edit['is_available'])||$edit['is_available']?'checked':'' ?>> Available to customers</label><button class="btn"><?= $edit?'Save changes':'Add food item' ?></button><?php if($edit): ?><a href="foods.php" class="text-link">Cancel edit</a><?php endif; ?></form></section>
<section><h2 class="subheading">Food items</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Category</th><th>Price</th><th>Available</th><th>Actions</th></tr></thead><tbody><?php foreach($foods as $f): ?><tr><td><?= e($f['name']) ?></td><td><?= e($f['category_name']??'—') ?></td><td><?= money($f['price']) ?></td><td><?= $f['is_available']?'Yes':'No' ?></td><td><a href="foods.php?edit=<?= (int)$f['id'] ?>">Edit</a> <form class="inline-form" method="post" onsubmit="return confirm('Delete this food item?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$f['id'] ?>"><button class="link-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<?php require '../includes/footer.php'; ?>
